      "Не чырыкалі, пахаваліся пад страхою вераб'і, толькі над прысадамі ля гасцінца каркала, лятала вялікая чарада галодных варон.",
      "Паглядзеў на слупок тэрмометра. Ён паказваў мінус дваццаць шэсць.",
