      "Калі адыходзіў ад студні, у веснічках, у зімовым паліто з паднятым каўняром, валёнках і цёплай авечай шапцы паказаўся дзед Пятрок, сусед. Згорбіўшыся, з вядром, ён таксама тупаў да студні за вадою, але раптам спыніўся, паказаў рукою на страху і сказаў:",
