      "Заміраюць галасы людскія,",
      "гукі абуджальнае вясны,",
      "і плывуць трывожныя такія,",
      "тонкія жалобныя званы.",
      "Пакружыўся над Хатынню бусел",
      "і паплыў у светлую смугу.",
      "Ён не ведаў болю Беларусі,",
